        const BindingFlags InstanceMembers = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
        const BindingFlags StaticMembers = BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic;

        public static dynamic? getattr(object? o, string name) =>
            TryGetAttr(o, name, out var v) ? v : throw new MissingMemberException($"'{(o == null ? "NoneType" : o is Type ? "type" : PyTypeName(o.GetType()))}' object has no attribute '{name}'");
        public static dynamic? getattr(object? o, string name, object? @default) => TryGetAttr(o, name, out var v) ? v : @default;
        public static bool hasattr(object? o, string name) => TryGetAttr(o, name, out _);

        /// <summary>
        /// An attribute by name: a property or field (of a class: a class variable), a method as a bound method, an
        /// attribute set on the object at run time, one of str's/list's/... Python methods, or a dynamic object's member.
        /// </summary>
        static bool TryGetAttr(object? o, string name, out object? value)
        {
            value = null;
            if (o == null || name.StartsWith("<")) return false;
            if (o is Type t)
            {
                if (name == "__name__" || name == "__qualname__") { value = PyTypeName(t); return true; }
                if (t.GetProperty(name, StaticMembers) is PropertyInfo sp && sp.GetIndexParameters().Length == 0) { value = sp.GetValue(null); return true; }
                if (t.GetField(name, StaticMembers) is FieldInfo sf) { value = sf.GetValue(null); return true; }
                if (t.GetMethods(StaticMembers | InstanceMembers).Any(m => m.Name == name)) { value = new PyBoundMethod(t, name); return true; }
                return false;
            }
            if (o is PyFunction pf)
            {
                switch (name)
                {
                    case "__name__": case "__qualname__": value = pf.__name__; return true;
                    case "__doc__": value = pf.__doc__; return true;
                    case "__wrapped__": if (pf.__wrapped__ == null) return false; value = pf.__wrapped__; return true;
                    case "__module__": value = pf.__module__; return true;
                }
                if (pf._attrs != null && pf._attrs.TryGetValue(name, out value)) return true;
            }
            var type = o.GetType();
            if (type.GetProperty(name, InstanceMembers) is PropertyInfo p && p.GetIndexParameters().Length == 0) { value = p.GetValue(o); return true; }
            if (type.GetField(name, InstanceMembers) is FieldInfo f) { value = f.GetValue(o); return true; }
            if (type.GetMethods(BindingFlags.Instance | BindingFlags.Public).Any(m => m.Name == name)) { value = new PyBoundMethod(o, name); return true; }
            if (type.GetProperty(name, StaticMembers) is PropertyInfo csp && csp.GetIndexParameters().Length == 0) { value = csp.GetValue(null); return true; }
            if (type.GetField(name, StaticMembers) is FieldInfo csf) { value = csf.GetValue(null); return true; }
            if (PyAttrDict.TryGetExtra(o, name, out value)) return true;
            switch (name)
            {
                case "__class__": value = type; return true;
                case "__dict__": value = new PyAttrDict(o); return true;
            }
            // Python's methods of built-in values ("abc".upper, xs.count): Builtins' extension methods for this value
            var candidates = typeof(Builtins).GetMethods(BindingFlags.Static | BindingFlags.Public)
                .Where(m => m.Name == name && m.IsDefined(typeof(System.Runtime.CompilerServices.ExtensionAttribute), false))
                .Select(m => CloseFor(m, o.GetType())).Where(m => m != null && m.GetParameters()[0].ParameterType.IsInstanceOfType(o)).ToList();
            if (candidates.Count > 0)
            {
                var self = o;
                value = new PyClosure(name, (a, kw) => InvokeExtension(name, candidates!, self, a));
                return true;
            }
            if (o is System.Dynamic.IDynamicMetaObjectProvider)
            {
                try
                {
                    var site = System.Runtime.CompilerServices.CallSite<Func<System.Runtime.CompilerServices.CallSite, object, object>>.Create(
                        Microsoft.CSharp.RuntimeBinder.Binder.GetMember(Microsoft.CSharp.RuntimeBinder.CSharpBinderFlags.None, name, typeof(Builtins),
                            new[] { Microsoft.CSharp.RuntimeBinder.CSharpArgumentInfo.Create(Microsoft.CSharp.RuntimeBinder.CSharpArgumentInfoFlags.None, null) }));
                    value = site.Target(site, o);
                    return true;
                }
                catch (Microsoft.CSharp.RuntimeBinder.RuntimeBinderException) { return false; }
                catch (MissingMemberException) { return false; }
            }
            return false;
        }

        /// <summary>A generic extension method closed over the receiver's element type (count&lt;T&gt;(this List&lt;T&gt;, T) for a List&lt;long&gt;).</summary>
        static MethodInfo? CloseFor(MethodInfo m, Type receiver)
        {
            if (!m.IsGenericMethodDefinition) return m;
            var typeArgs = m.GetGenericArguments();
            var p0 = m.GetParameters()[0].ParameterType;
            if (typeArgs.Length != 1 || !p0.IsGenericType) return null;
            var def = p0.GetGenericTypeDefinition();
            var match = receiver.IsGenericType && receiver.GetGenericTypeDefinition() == def ? receiver
                : receiver.GetInterfaces().FirstOrDefault(i => i.IsGenericType && i.GetGenericTypeDefinition() == def);
            int at = Array.IndexOf(p0.GetGenericArguments(), typeArgs[0]);
            if (match == null || at < 0) return null;
            try { return m.MakeGenericMethod(match.GetGenericArguments()[at]); } catch (ArgumentException) { return null; }
        }

        static object? InvokeExtension(string name, List<MethodInfo?> candidates, object self, object?[] args)
        {
            foreach (var m in candidates)
            {
                var ps = m!.GetParameters();
                int required = ps.Count(x => !x.IsOptional);
                if (args.Length + 1 < required || args.Length + 1 > ps.Length) continue;
                var call = new object?[ps.Length];
                call[0] = self;
                try
                {
                    for (int i = 1; i < ps.Length; i++) call[i] = i - 1 < args.Length ? ConvertTo(args[i - 1], ps[i].ParameterType) : ps[i].DefaultValue;
                }
                catch (Exception e) when (e is InvalidCastException || e is FormatException) { continue; }
                try { return m.Invoke(null, call); }
                catch (TargetInvocationException tie) when (tie.InnerException != null)
                {
                    System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(tie.InnerException).Throw();
                    throw;
                }
                catch (ArgumentException) { continue; }
            }
            throw new InvalidCastException($"{name}() does not take {args.Length} arguments here");
        }

        /// <summary>setattr(obj, name, value): a declared property or field (converted to its type), else an attribute kept beside the object.</summary>
        public static void setattr(object? o, string name, object? value)
        {
            if (o == null) throw new MissingMemberException($"'NoneType' object has no attribute '{name}'");
            if (o is Type t)
            {
                if (t.GetProperty(name, StaticMembers) is PropertyInfo sp && sp.CanWrite) { sp.SetValue(null, ConvertTo(value, sp.PropertyType)); return; }
                if (t.GetField(name, StaticMembers) is FieldInfo sf && !sf.IsInitOnly) { sf.SetValue(null, ConvertTo(value, sf.FieldType)); return; }
                throw new MissingMemberException($"type object '{PyTypeName(t)}' has no attribute '{name}' (Typhon classes cannot gain attributes at run time)");
            }
            if (o is PyFunction pf)
            {
                switch (name)
                {
                    case "__name__": case "__qualname__": pf.__name__ = (string)value!; return;
                    case "__doc__": pf.__doc__ = value; return;
                    case "__wrapped__": pf.__wrapped__ = value; return;
                    case "__module__": pf.__module__ = (string)value!; return;
                }
                (pf._attrs ??= new Dictionary<string, object?>())[name] = value;
                return;
            }
            var type = o.GetType();
            if (type.GetProperty(name, InstanceMembers) is PropertyInfo p && p.CanWrite && p.GetIndexParameters().Length == 0) { p.SetValue(o, ConvertTo(value, p.PropertyType)); return; }
            if (type.GetField(name, InstanceMembers) is FieldInfo f && !f.IsInitOnly) { f.SetValue(o, ConvertTo(value, f.FieldType)); return; }
            new PyAttrDict(o)[name] = value;
        }

        public static void delattr(object? o, string name)
        {
            if (o != null && PyAttrDict.RemoveExtra(o, name)) return;
            if (o is PyFunction pf && pf._attrs != null && pf._attrs.Remove(name)) return;
            throw new MissingMemberException($"'{(o == null ? "NoneType" : PyTypeName(o.GetType()))}' object has no attribute '{name}' (or it is declared by its class)");
        }

        static object? ConvertTo(object? v, Type t) =>
            v == null || t.IsInstanceOfType(v) || t == typeof(object) ? v
            : System.Convert.ChangeType(v, Nullable.GetUnderlyingType(t) ?? t, System.Globalization.CultureInfo.InvariantCulture);
    }
